    /*
     * Add to the SerialNumbers
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	InventoryTransaction
     */
    public InventoryTransaction addToSerialNumbers( UUID parentId, SerialNumber addTo ) {
	    LOGGER.info("handling AssignSerialNumbersToInventoryTransactionEvent - " );
	    
	    InventoryTransaction parentEntity = repository.findById(parentId).get();
	    SerialNumber child = registry.project( SerialNumber.class, addTo.getSerialNumberId());
	    
	    parentEntity.getSerialNumbers().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the SerialNumbers
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	InventoryTransaction
     */
	public InventoryTransaction removeFromSerialNumbers( UUID parentId, SerialNumber removeFrom ) {
	    LOGGER.info("handling RemoveSerialNumbersFromInventoryTransactionEvent " );
	
	    InventoryTransaction parentEntity = repository.findById(parentId).get();
	    SerialNumber child = registry.project( SerialNumber.class, removeFrom.getSerialNumberId());
	    
	    parentEntity.getSerialNumbers().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



